static updateKeyMap = function() {
	length = array_length(values);

	if(!prop.is_anim && !LOADING && !APPENDING) return;
	if(array_empty(values)) { array_resize(key_map, NODE_TOTAL_FRAMES); return; }

	checkFreeze();

	var _len = max(NODE_TOTAL_FRAMES, array_last(values).time);
	key_map_mode = prop.on_end;
	key_map      = array_verify(key_map, _len);

	if(prop.type == VALUE_TYPE.trigger) {
		for( var i = 0; i < _len; i++ ) 
			key_map[i] = 0;

		for( var i = 0, n = length; i < n; i++ )
			key_map[values[i].time] = true;
		return;
	} 

	if(length < 2) {
		for( var i = 0; i < _len; i++ ) 
			key_map[i] = 0;
		return;
	}

	var _firstKey = values[0].time;
	for( var i = 0; i < _firstKey; i++ ) 
		key_map[i] = -1;

	var _keyIndex = _firstKey;

	for( var i = 1, n = length; i < n; i++ ) {
		var _k1 = values[i].time;

		for( var j = max(0, _keyIndex); j < _k1; j++ ) 
			key_map[j] = i - 1;

		_keyIndex = _k1;
	}

	for( var i = max(0, _keyIndex); i < _len; i++ ) 
		key_map[i] = infinity;

	node.animation_range_update = true;

function  array_verify(arr, length) { INLINE
	if(!is_array(arr)) return array_create(length);
	if(array_length(arr) == length) return arr;

	array_resize(arr, length);
	return arr;
}

function array_safe_get_fast(arr, index=0, def=0) {
	if(is(arr, ArrayObject)) return arr.getElementByIndex(index);
	return is_array(arr) && index >= 0 && index < array_length(arr)? arr[index] : def;
}
